rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /probe/access-10 {
      allow get: if get(/databases/$(database)/documents/access/a0).data.allowed == true &&
        get(/databases/$(database)/documents/access/a1).data.allowed == true &&
        get(/databases/$(database)/documents/access/a2).data.allowed == true &&
        get(/databases/$(database)/documents/access/a3).data.allowed == true &&
        get(/databases/$(database)/documents/access/a4).data.allowed == true &&
        get(/databases/$(database)/documents/access/a5).data.allowed == true &&
        get(/databases/$(database)/documents/access/a6).data.allowed == true &&
        get(/databases/$(database)/documents/access/a7).data.allowed == true &&
        get(/databases/$(database)/documents/access/a8).data.allowed == true &&
        get(/databases/$(database)/documents/access/a9).data.allowed == true;
    }
    match /probe/access-11 {
      allow get: if get(/databases/$(database)/documents/access/a0).data.allowed == true &&
        get(/databases/$(database)/documents/access/a1).data.allowed == true &&
        get(/databases/$(database)/documents/access/a2).data.allowed == true &&
        get(/databases/$(database)/documents/access/a3).data.allowed == true &&
        get(/databases/$(database)/documents/access/a4).data.allowed == true &&
        get(/databases/$(database)/documents/access/a5).data.allowed == true &&
        get(/databases/$(database)/documents/access/a6).data.allowed == true &&
        get(/databases/$(database)/documents/access/a7).data.allowed == true &&
        get(/databases/$(database)/documents/access/a8).data.allowed == true &&
        get(/databases/$(database)/documents/access/a9).data.allowed == true &&
        get(/databases/$(database)/documents/access/a10).data.allowed == true;
    }
    match /probe/cached-11 {
      allow get: if get(/databases/$(database)/documents/access/a0).data.allowed == true &&
        get(/databases/$(database)/documents/access/a0).data.allowed == true &&
        get(/databases/$(database)/documents/access/a0).data.allowed == true &&
        get(/databases/$(database)/documents/access/a0).data.allowed == true &&
        get(/databases/$(database)/documents/access/a0).data.allowed == true &&
        get(/databases/$(database)/documents/access/a0).data.allowed == true &&
        get(/databases/$(database)/documents/access/a0).data.allowed == true &&
        get(/databases/$(database)/documents/access/a0).data.allowed == true &&
        get(/databases/$(database)/documents/access/a0).data.allowed == true &&
        get(/databases/$(database)/documents/access/a0).data.allowed == true &&
        get(/databases/$(database)/documents/access/a0).data.allowed == true;
    }
    match /probe/exists-10 {
      allow get: if exists(/databases/$(database)/documents/access/e0) &&
        exists(/databases/$(database)/documents/access/e1) &&
        exists(/databases/$(database)/documents/access/e2) &&
        exists(/databases/$(database)/documents/access/e3) &&
        exists(/databases/$(database)/documents/access/e4) &&
        exists(/databases/$(database)/documents/access/e5) &&
        exists(/databases/$(database)/documents/access/e6) &&
        exists(/databases/$(database)/documents/access/e7) &&
        exists(/databases/$(database)/documents/access/e8) &&
        exists(/databases/$(database)/documents/access/e9);
    }
    match /probe/exists-11 {
      allow get: if exists(/databases/$(database)/documents/access/e0) &&
        exists(/databases/$(database)/documents/access/e1) &&
        exists(/databases/$(database)/documents/access/e2) &&
        exists(/databases/$(database)/documents/access/e3) &&
        exists(/databases/$(database)/documents/access/e4) &&
        exists(/databases/$(database)/documents/access/e5) &&
        exists(/databases/$(database)/documents/access/e6) &&
        exists(/databases/$(database)/documents/access/e7) &&
        exists(/databases/$(database)/documents/access/e8) &&
        exists(/databases/$(database)/documents/access/e9) &&
        exists(/databases/$(database)/documents/access/e10);
    }
    match /batch/{id} {
      allow create, update: if exists(/databases/$(database)/documents/access/$(id));
    }
    match /state/counter {
      allow update: if request.resource.data.version == resource.data.version + 1;
    }
    match /atomic/{id} {
      allow create: if getAfter(/databases/$(database)/documents/state/counter).data.version == request.resource.data.expectedVersion;
    }
    match /runtime/missing-field {
      allow get: if resource.data.missing == true;
    }
    match /runtime/division-zero {
      allow get: if 1 / 0 == 0;
    }
    match /runtime/list-out-of-bounds {
      allow get: if [1][2] == 1;
    }
    match /runtime/wrong-type-method {
      allow get: if resource.data.ordinal.size() == 1;
    }
    match /runtime/missing-get-resource {
      allow get: if get(/databases/$(database)/documents/missing/document).data.allowed == true;
    }
  }
}

